<template>
  <el-config-provider :locale="zhCn">
  <section class="admin-page certificate-admin">
    <AdminPageHeader title="证书管理" eyebrow="会议管理" :subtitle="project ? '每场会议独立配置，保存草稿后另行发布。' : '管理各场会议的专属查询页面、模板与获证名单。'">
      <template #actions>
        <el-button :disabled="busy" @click="refresh">刷新</el-button>
        <template v-if="project"><el-button :disabled="busy" @click="leave">返回会议列表</el-button><el-button v-if="can('write')" type="primary" :loading="busy" :disabled="!dirty" @click="save">保存草稿</el-button></template>
        <el-button v-else-if="can('write')" type="primary" :disabled="busy" @click="createVisible = true">新建证书项目</el-button>
      </template>
    </AdminPageHeader>
    <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" class="cert-alert" />
    <section v-if="!project" v-loading="busy" class="table-panel"><div class="cert-toolbar"><el-input v-model="projectKeyword" clearable placeholder="搜索会议或证书项目" aria-label="搜索证书项目" style="max-width:360px" /></div>
      <el-table :data="filteredProjects" empty-text="还没有证书项目，可以为会议创建第一个项目。">
        <AdminTableIndex />
        <el-table-column label="会议证书项目" min-width="230"><template #default="{ row }"><strong>{{ row.name }}</strong><div class="cert-muted cert-url">{{ row.publicUrl }}</div></template></el-table-column>
        <el-table-column label="状态" width="160"><template #default="{ row }"><el-tag :type="row.publishedRevision === null || row.paused ? 'warning' : 'success'">{{ row.publishedRevision === null ? '未发布' : row.paused ? '已暂停' : '已发布 · 可访问' }}</el-tag><el-tag v-if="row.archived" type="info">已归档</el-tag><div class="cert-muted">草稿 V{{ row.draftRevision }} / 发布 {{ row.publishedRevision === null ? '无' : `V${row.publishedRevision}` }}</div></template></el-table-column>
        <el-table-column label="名单 / 发证" width="120"><template #default="{ row }">{{ row._count.recipients }} / {{ row._count.issues }}</template></el-table-column>
        <el-table-column label="操作" width="190"><template #default="{ row }"><el-button link type="primary" :disabled="busy" @click="open(row.id)">管理</el-button><el-button link :disabled="!row.publishedRevision" @click="visit(row.publicUrl)">查看领取页</el-button></template></el-table-column>
      </el-table>
    </section>

    <template v-else-if="draft">
      <div class="cert-project-bar"><div><strong>{{ project.draft.name }}</strong><el-tag :type="dirty ? 'warning' : 'info'">{{ dirty ? '有未保存更改' : `草稿 V${project.draftRevision}` }}</el-tag><el-tag v-if="project.publishedRevision" :type="project.paused ? 'warning' : 'success'">{{ project.paused ? '暂停领取' : `已发布 V${project.publishedRevision}` }}</el-tag><el-tag v-if="project.archived" type="info">已归档</el-tag></div><el-select :model-value="project.id" aria-label="切换管理会议" filterable :disabled="busy" @change="open"><el-option v-for="p in projects" :key="p.id" :value="p.id" :label="p.name" /></el-select></div>
      <el-tabs v-model="tab" :before-leave="() => !busy">
        <el-tab-pane label="基本信息" name="basic" :disabled="busy">
          <section class="cert-panel"><el-form label-position="top" :disabled="!can('write') || busy" @submit.prevent>
            <div class="cert-grid"><el-form-item label="项目名称" required><el-input v-model="draft.name" maxlength="200" /></el-form-item><el-form-item label="查询页面标题" required><el-input v-model="draft.title" maxlength="200" /></el-form-item><el-form-item label="发证日期"><el-input v-model="draft.issueDate" placeholder="例如：2026年11月4日" maxlength="60" /></el-form-item><el-form-item label="自动编号前缀"><el-input v-model="draft.numberPrefix" maxlength="32" /></el-form-item><el-form-item label="页面主题色"><el-color-picker v-model="draft.primaryColor" /></el-form-item><el-form-item label="查询页主视觉"><el-select v-model="draft.backgroundAssetId" clearable placeholder="选择已上传图片"><el-option v-for="a in assets.filter(a => a.kind === 'image')" :key="a.id" :value="a.id" :label="a.name" /></el-select><label class="cert-file">上传主视觉<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="upload($event, 'background')" /></label></el-form-item></div>
            <el-form-item label="页面说明"><el-input v-model="draft.description" type="textarea" :rows="3" maxlength="2000" /></el-form-item><el-form-item label="联系方式与资料更正说明"><el-input v-model="draft.contact" maxlength="500" /></el-form-item>
          </el-form><div class="cert-link-box"><span>会议专属链接（修改名称不改变链接）</span><div><code>{{ project.publicUrl }}</code><el-button size="small" @click="copyLink">复制链接</el-button></div></div></section>
          <section class="cert-panel"><div class="cert-toolbar"><h3>自定义名单字段</h3><el-button v-if="can('write')" :disabled="busy" @click="draft.customFields.push({ key: `field_${draft.customFields.length + 1}`, label: '新字段' })">添加字段</el-button></div><div v-for="(f, i) in draft.customFields" :key="i" class="cert-inline"><el-input v-model="f.key" aria-label="字段标识" placeholder="英文唯一标识" :disabled="!can('write')" /><el-input v-model="f.label" aria-label="字段名称" placeholder="显示名称" :disabled="!can('write')" /><el-button v-if="can('write')" @click="draft.customFields.splice(i, 1)">移除</el-button></div><p class="cert-muted">这些字段可用于导入、查询条件、获证条件和证书文字。修改字段标识前请处理相关模板与规则。</p></section>
        </el-tab-pane>
        <el-tab-pane label="证书模板" name="template" :disabled="busy">
          <section class="cert-panel"><div class="cert-toolbar"><el-select v-model="templateId" aria-label="证书类型"><el-option v-for="t in draft.templates" :key="t.id" :value="t.id" :label="t.name" /></el-select><div><el-button v-if="can('write')" @click="addTemplate">新增证书类型</el-button><el-button :loading="previewBusy" @click="preview()">正式图片预览</el-button></div></div>
            <div v-if="template" class="cert-template-grid"><div><div class="cert-paper" :style="{ aspectRatio: `${template.width}/${template.height}` }" @pointermove="moveField" @pointerup="dragging = false" @pointercancel="dragging = false"><img v-if="backgroundUrl" :src="backgroundUrl" alt="证书底图" draggable="false" /><button v-for="f in template.fields" :key="f.id" type="button" class="cert-overlay-field" :class="{ selected: fieldId === f.id }" :style="fieldStyle(f)" :aria-label="`调整${f.label}位置`" @pointerdown="startField($event, f)">{{ fieldText(f) }}</button></div><p class="cert-muted">点击文字选择字段，拖动调整位置。正式图片预览与嘉宾下载使用同一生成器。</p><label v-if="can('write')" class="cert-file">上传证书底图（PNG / JPG）<input type="file" accept="image/png,image/jpeg" :disabled="busy" @change="upload($event, 'template')" /></label></div>
              <el-form class="cert-properties" label-position="top" :disabled="!can('write') || busy" @submit.prevent><el-form-item label="证书类型名称"><el-input v-model="template.name" /></el-form-item><div class="cert-grid"><el-form-item label="宽度 px"><el-input-number v-model="template.width" :min="400" :max="4000" :precision="0" /></el-form-item><el-form-item label="高度 px"><el-input-number v-model="template.height" :min="300" :max="4000" :precision="0" /></el-form-item></div><el-form-item label="底图"><el-select v-model="template.assetId" clearable><el-option v-for="a in assets.filter(a => a.kind === 'image')" :key="a.id" :value="a.id" :label="a.name" /></el-select></el-form-item><el-form-item label="字体文件"><el-select v-model="template.fontAssetId" clearable placeholder="服务器默认字体"><el-option v-for="a in assets.filter(a => a.kind === 'font')" :key="a.id" :value="a.id" :label="a.name" /></el-select><label class="cert-file">上传字体<input type="file" accept=".ttf,.otf,.ttc" :disabled="busy" @change="upload($event, 'font')" /></label></el-form-item><el-form-item label="默认字体（未选择字体文件时）"><el-input v-model="template.fontFamily" :disabled="Boolean(template.fontAssetId)" /><p v-if="template.fontAssetId" class="cert-muted">正式生成时使用所选字体文件。</p></el-form-item>
                <el-divider>文字字段</el-divider><el-form-item label="当前文字"><el-select v-model="fieldId"><el-option v-for="f in template.fields" :key="f.id" :value="f.id" :label="f.label" /></el-select></el-form-item><template v-if="field"><el-form-item label="字段名称"><el-input v-model="field.label" /></el-form-item><el-form-item label="文字来源"><el-select v-model="field.key"><el-option v-for="f in textFieldOptions" :key="f.key" :value="f.key" :label="f.label" /></el-select></el-form-item><el-form-item v-if="field.key === 'literal'" label="固定文字"><el-input v-model="field.text" type="textarea" /></el-form-item><el-form-item v-if="field.key !== 'literal'" label="字段前缀（可选）"><el-input v-model="field.text" /></el-form-item><div class="cert-grid"><el-form-item label="X %"><el-input-number v-model="field.x" :min="0" :max="100" :precision="1" /></el-form-item><el-form-item label="Y %"><el-input-number v-model="field.y" :min="0" :max="100" :precision="1" /></el-form-item><el-form-item label="字号 px"><el-input-number v-model="field.size" :min="8" :max="300" /></el-form-item><el-form-item label="颜色"><el-color-picker v-model="field.color" /></el-form-item><el-form-item label="最大宽度 %"><el-input-number v-model="field.maxWidth" :min="1" :max="100" /></el-form-item><el-form-item label="最多行数"><el-input-number v-model="field.maxLines" :min="1" :max="10" :precision="0" /></el-form-item><el-form-item label="行高倍数"><el-input-number v-model="field.lineHeight" :min="1" :max="3" :step="0.1" /></el-form-item><el-form-item label="字重"><el-select v-model="field.weight"><el-option :value="400" label="常规" /><el-option :value="700" label="加粗" /></el-select></el-form-item></div><el-form-item label="对齐"><el-radio-group v-model="field.align"><el-radio-button value="start">左</el-radio-button><el-radio-button value="middle">中</el-radio-button><el-radio-button value="end">右</el-radio-button></el-radio-group></el-form-item></template><div class="cert-toolbar"><el-button @click="addTextField">添加文字</el-button><el-button :disabled="template.fields.length <= 1" @click="removeTextField">移除文字</el-button></div><el-button v-if="draft.templates.length > 1" type="danger" plain @click="removeTemplate">移除此证书类型</el-button>
              </el-form></div>
          </section>
        </el-tab-pane>
        <el-tab-pane label="获证名单" name="roster" :disabled="busy">
          <section class="cert-panel"><div class="cert-toolbar"><div class="cert-inline"><el-input v-model="keyword" placeholder="搜索姓名或证书编号" clearable aria-label="搜索证书名单" @keyup.enter="loadRoster(1)" /><el-button @click="loadRoster(1)">查询</el-button></div><div class="cert-inline"><el-button v-if="can('write')" :disabled="dirty || busy" @click="editPerson()">新增人员</el-button><el-button v-if="can('import')" :disabled="dirty || busy" @click="showImport">导入名单</el-button><el-button v-if="can('export')" :disabled="busy" @click="exportRoster">导出</el-button></div></div><p v-if="dirty" class="cert-muted">请先保存配置草稿，再维护名单。</p><el-table :data="people" row-key="id"><AdminTableIndex /><el-table-column label="姓名 / 单位" min-width="180"><template #default="{ row }">{{ row.name }}<div class="cert-muted">{{ row.organization }}</div></template></el-table-column><el-table-column label="证书类型" min-width="120"><template #default="{ row }">{{ draft.templates.find(t => t.id === row.templateId)?.name || row.templateId }}</template></el-table-column><el-table-column prop="certificateNo" label="编号" min-width="170" /><el-table-column label="领取码" width="90"><template #default="{ row }">{{ row.hasClaimCode ? '已设置' : '未设置' }}</template></el-table-column><el-table-column label="资格" width="90"><template #default="{ row }"><el-tag :type="row.eligible ? 'success' : 'info'">{{ row.eligible ? '已确认' : '待确认' }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{ row }"><el-button link @click="preview(row.id, row.templateId)">预览</el-button><el-button v-if="can('write')" link :disabled="dirty || busy" @click="editPerson(row)">更正</el-button><el-button v-if="can('write')" link type="danger" :disabled="dirty || busy" @click="removePerson(row)">移除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="50" :total="total" layout="total, prev, pager, next" :disabled="busy" @current-change="loadRoster" /></section>
        </el-tab-pane>
        <el-tab-pane label="规则配置" name="rules" :disabled="busy">
          <section class="cert-panel"><h3>查询条件</h3><div v-for="option in queryOptions" :key="option.key" class="cert-query-row"><span>{{ option.label }}</span><el-checkbox :model-value="Boolean(queryField(option.key))" :disabled="!can('write')" @change="toggleQuery(option)">启用</el-checkbox><el-checkbox v-if="queryField(option.key)" v-model="queryField(option.key)!.required" :disabled="!can('write')">必填</el-checkbox></div><p class="cert-muted">所有已填写条件精确组合匹配；多条匹配时要求补充信息。</p></section>
          <section class="cert-panel"><h3>获证资格</h3><el-form label-position="top" :disabled="!can('write') || busy" @submit.prevent><el-form-item label="资格判断方式"><el-select v-model="draft.eligibility.mode"><el-option value="approved" label="名单中已确认发证资格的人员" /><el-option value="all" label="名单中的全部人员" /><el-option value="conditions" label="按名单字段条件判断" /></el-select></el-form-item><template v-if="draft.eligibility.mode === 'conditions'"><el-radio-group v-model="draft.eligibility.match"><el-radio value="all">满足全部条件</el-radio><el-radio value="any">满足任一条件</el-radio></el-radio-group><div v-for="(condition, i) in draft.eligibility.conditions" :key="i" class="cert-inline cert-condition"><el-select v-model="condition.field" aria-label="获证条件字段"><el-option v-for="f in queryOptions.filter(f => f.key !== 'claimCode')" :key="f.key" :value="f.key" :label="f.label" /></el-select><el-select v-model="condition.operator" aria-label="获证条件比较方式"><el-option value="equals" label="等于" /><el-option value="in" label="属于以下值" /><el-option value="notEmpty" label="不为空" /></el-select><el-input v-if="condition.operator !== 'notEmpty'" v-model="condition.value" placeholder="多个值用逗号分隔" aria-label="获证条件值" /><el-button @click="draft.eligibility.conditions.splice(i, 1)">移除</el-button></div><el-button @click="draft.eligibility.conditions.push({ field: 'organization', operator: 'equals', value: '' })">添加条件</el-button></template><div class="cert-grid"><el-form-item label="开放时间（留空为发布后开放）"><el-date-picker v-model="draft.startsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" clearable /></el-form-item><el-form-item label="截止时间（留空为持续开放）"><el-date-picker v-model="draft.endsAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" clearable /></el-form-item></div><el-form-item label="重复下载"><el-switch v-model="draft.allowRepeatDownload" active-text="允许重复下载" inactive-text="仅允许一次下载" /></el-form-item><el-form-item label="未查询到时的提示"><el-input v-model="draft.notFoundMessage" type="textarea" :rows="2" maxlength="500" /></el-form-item></el-form></section>
        </el-tab-pane>
        <el-tab-pane label="预览与发布" name="publish" :disabled="busy">
          <section class="cert-panel"><div class="cert-grid"><div><h3>当前草稿 V{{ project.draftRevision }}</h3><p class="cert-muted">{{ dirty ? '有未保存更改，发布前需先保存。' : '配置与名单已保存为草稿。' }}</p><el-button :loading="previewBusy" @click="preview()">预览当前草稿</el-button></div><div><h3>嘉宾当前访问 {{ project.publishedRevision ? `V${project.publishedRevision}` : '尚未开放' }}</h3><el-button :disabled="!project.publishedRevision" @click="visit(project.publicUrl)">查看已发布页面</el-button><el-button :disabled="!project.publishedRevision" @click="preview(undefined, undefined, project.publishedRevision!)">已发布图片预览</el-button></div></div><el-divider /><div class="cert-link-box"><span>会议专属链接</span><code>{{ project.publicUrl }}</code><el-button size="small" @click="copyLink">复制链接</el-button></div><div class="cert-toolbar"><el-button v-if="can('publish')" type="primary" :disabled="dirty || busy" @click="publish">发布已保存版本</el-button><el-button v-if="can('publish') && project.publishedRevision" :disabled="busy || dirty" @click="togglePause">{{ project.paused ? '恢复本会议领取' : '暂停本会议领取' }}</el-button><el-button v-if="can('publish')" :disabled="busy || dirty" @click="toggleArchive">{{ project.archived ? '取消归档' : '归档项目' }}</el-button></div><p class="cert-muted">发布仅更新本会议；其他会议继续使用自己的已发布配置。发布前会校验模板、获证名单及必填查询信息。</p></section>
          <section class="cert-panel"><h3>发布历史（最近 50 版）</h3><el-table :data="project.versions"><el-table-column label="版本" width="100"><template #default="{ row }">V{{ row.revision }}</template></el-table-column><el-table-column label="发布时间" min-width="170"><template #default="{ row }">{{ date(row.createdAt) }}</template></el-table-column><el-table-column label="名单" width="100"><template #default="{ row }">{{ row._count.recipients }}</template></el-table-column><el-table-column label="操作" min-width="150"><template #default="{ row }"><el-button v-if="can('write') && can('import')" link :disabled="busy || dirty" @click="restore(row.revision)">复制到草稿</el-button></template></el-table-column></el-table></section>
          <section class="cert-panel"><div class="cert-toolbar"><h3>发证记录（最近 500 条）</h3><el-button @click="loadIssues">刷新记录</el-button></div><el-table :data="issues"><el-table-column prop="name" label="姓名" min-width="130" /><el-table-column prop="certificateNo" label="证书编号" min-width="160" /><el-table-column label="版本" width="90"><template #default="{ row }">V{{ row.version.revision }}</template></el-table-column><el-table-column prop="downloadCount" label="下载次数" width="100" /><el-table-column label="状态" width="100"><template #default="{ row }">{{ row.revokedAt ? '已撤销' : '有效' }}</template></el-table-column><el-table-column v-if="can('publish')" label="操作" width="120"><template #default="{ row }"><el-button link :type="row.revokedAt ? 'primary' : 'danger'" :disabled="busy" @click="revoke(row)">{{ row.revokedAt ? '恢复领取' : '撤销领取' }}</el-button></template></el-table-column></el-table></section>
        </el-tab-pane>
      </el-tabs>
    </template>

    <el-dialog v-model="createVisible" title="新建会议证书项目" width="min(560px, calc(100vw - 24px))" :close-on-click-modal="false"><el-form label-position="top" :disabled="busy" @submit.prevent><el-form-item label="项目名称" required><el-input v-model="createForm.name" maxlength="200" /></el-form-item><el-form-item label="关联会议"><el-select v-model="createForm.conferenceId" clearable filterable placeholder="历史活动可暂不关联"><el-option v-for="c in options" :key="c.id" :value="c.id" :label="c.title" /></el-select></el-form-item><el-form-item label="初始配置"><el-select v-model="createForm.copyFromId" clearable placeholder="空白配置"><el-option v-for="p in projects" :key="p.id" :value="p.id" :label="`复制 ${p.name}`" /></el-select></el-form-item><p class="cert-muted">复制模板、素材和规则，名单另行导入，各会议分别维护。</p></el-form><template #footer><el-button @click="createVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="create">创建</el-button></template></el-dialog>
    <el-dialog v-model="personVisible" :title="person.id ? '更正名单记录' : '新增获证人员'" width="min(680px, calc(100vw - 24px))" :close-on-click-modal="false"><el-form v-if="draft" label-position="top" :disabled="busy" @submit.prevent><div class="cert-grid"><el-form-item label="姓名" required><el-input v-model="person.name" /></el-form-item><el-form-item label="单位"><el-input v-model="person.organization" /></el-form-item><el-form-item label="职务"><el-input v-model="person.role" /></el-form-item><el-form-item label="证书编号（留空自动生成）"><el-input v-model="person.certificateNo" /></el-form-item><el-form-item label="证书类型"><el-select v-model="person.templateId"><el-option v-for="t in draft.templates" :key="t.id" :value="t.id" :label="t.name" /></el-select></el-form-item><el-form-item :label="person.id ? '新领取码（留空保留原码）' : '领取码'"><el-input v-model="person.claimCode" autocomplete="off" /></el-form-item><el-form-item v-for="f in draft.customFields" :key="f.key" :label="f.label"><el-input v-model="person.custom[f.key]" /></el-form-item></div><el-checkbox v-model="person.eligible">确认具备发证资格</el-checkbox></el-form><template #footer><el-button @click="personVisible = false">取消</el-button><el-button type="primary" :loading="busy" @click="savePerson">保存到草稿</el-button></template></el-dialog>
    <el-dialog v-model="importVisible" title="导入获证名单" width="min(960px, calc(100vw - 24px))" :close-on-click-modal="false"><template v-if="draft"><el-alert v-if="importError" :title="importError" type="error" :closable="false" /><div class="cert-toolbar"><label class="cert-file">选择 Excel / CSV / TXT<input type="file" accept=".xlsx,.xls,.csv,.txt,.tsv" @change="readFile" /></label><el-button @click="downloadSample">下载标准模板</el-button><template v-if="project?.conferenceId && session.hasPermission('registration:view')"><el-input-number v-model="registrationPage" :min="1" :precision="0" aria-label="报名名单批次" /><el-button :loading="busy" @click="readRegistration">读取本会议报名名单</el-button></template><el-button v-if="sheet.length" @click="downloadCurrentImport">下载当前导入名单</el-button></div><el-input v-model="paste" type="textarea" :rows="3" placeholder="也可粘贴带表头的 CSV 或表格内容" @input="invalidatePaste" /><el-button style="margin-top:10px" @click="readPaste">解析粘贴内容</el-button><template v-if="sheet.length"><p class="cert-muted">共 {{ sheet.length - 1 }} 行。请核对字段映射。</p><div class="cert-grid"><el-form-item v-for="column in importColumns" :key="column.key" :label="column.label"><el-select v-model="mapping[column.key]" clearable @change="plan = null"><el-option v-for="(h, i) in sheet[0]" :key="i" :value="String(i)" :label="h || `第 ${i + 1} 列`" /></el-select></el-form-item><el-form-item label="导入到证书类型"><el-select v-model="importTemplate" @change="plan = null"><el-option v-for="t in draft.templates" :key="t.id" :value="t.id" :label="t.name" /></el-select></el-form-item><el-form-item label="导入方式"><el-select v-model="importMode" @change="plan = null"><el-option value="append" label="仅追加，编号冲突时阻止导入" /><el-option value="upsert" label="按证书类型与编号新增或更新" /><el-option value="replace" label="整批替换当前草稿名单" /></el-select></el-form-item></div><el-button :loading="busy" @click="checkImport">预检导入</el-button><section v-if="plan" class="cert-import-result"><strong>新增 {{ plan.added }} · 更新 {{ plan.updated }} · 移除 {{ plan.removed }} · 错误 {{ plan.errors.length }}</strong><el-table v-if="plan.errors.length" :data="plan.errors" max-height="240"><el-table-column prop="row" label="数据行" width="100" /><el-table-column prop="message" label="问题" /></el-table><p class="cert-muted">有错误时整批不写入。编号留空时按人员资料生成稳定编号；资料完全相同的不同人员请提供独立编号或唯一外部标识。</p><el-input v-if="importMode === 'replace'" v-model="replaceConfirmation" :placeholder="`确认替换请输入：${project?.publicId}`" /></section></template></template><template #footer><el-button @click="importVisible = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!plan || plan.errors.length > 0" @click="commitImport">确认写入草稿</el-button></template></el-dialog>
    <el-dialog v-model="previewVisible" title="服务端证书图片预览" width="min(1100px, calc(100vw - 24px))"><img v-if="previewUrl" class="cert-final-preview" :src="previewUrl" alt="正式生成的证书图片" /><p class="cert-muted">预览与下载使用相同排版规则；请核对姓名、单位、编号、中文字体和长文字。</p></el-dialog>
  </section>
  </el-config-provider>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
import zhCn from "element-plus/es/locale/lang/zh-cn";
import { CERTIFICATE_QUERY_FIELDS, defaultCertificateConfig, validateCertificateConfig, type CertificateConfig, type CertificateTextField, type CertificateFieldKey } from "@conference/shared";
import AdminPageHeader from "../../components/AdminPageHeader.vue";
import AdminTableIndex from "../../components/AdminTableIndex.vue";
import { certificates as api, type CertificateAsset, type CertificateDetail, type CertificateImportPlan, type CertificateIssue, type CertificateRecipient, type CertificateSummary } from "../../services/certificates";
import { useAdminSession } from "../../stores/admin-session";
import { routeQuery, navigateTo } from "../../router";
import { CERTIFICATE_COLUMNS, defaultCertificateMapping, downloadCertificateSheet, mapCertificateRows, readCertificateSheet } from "../../utils/certificate-import";

const session = useAdminSession(), can = (action: string) => session.hasPermission(`certificate:${action}`);
const projectKeyword = ref('');
const projects = ref<CertificateSummary[]>([]), options = ref<{ id: string; title: string }[]>([]), project = ref<CertificateDetail | null>(null), draft = ref<CertificateConfig | null>(null);
const busy = ref(false), previewBusy = ref(false), error = ref(""), tab = ref("basic"), templateId = ref("default"), fieldId = ref("name");
const people = ref<CertificateRecipient[]>([]), total = ref(0), page = ref(1), keyword = ref(""), assets = ref<CertificateAsset[]>([]), issues = ref<CertificateIssue[]>([]);
const createVisible = ref(false), createForm = reactive({ name: "", conferenceId: "", copyFromId: "" });
const personVisible = ref(false), person = reactive({ id: "", templateId: "default", name: "", organization: "", role: "", certificateNo: "", claimCode: "", eligible: false, custom: {} as Record<string, string> });
const previewVisible = ref(false), previewUrl = ref(""), backgroundUrl = ref("");
const registrationPage = ref(1);
const importVisible = ref(false), importError = ref(""), paste = ref(""), sheet = ref<string[][]>([]), mapping = ref<Record<string, string>>({}), importMode = ref("upsert"), importTemplate = ref("default"), plan = ref<CertificateImportPlan | null>(null), replaceConfirmation = ref("");
let importRows: unknown[] = [], loadSequence = 0, imageSequence = 0, previewSequence = 0;
const dragging = ref(false);
const clone = <T,>(v: T): T => JSON.parse(JSON.stringify(v));
const filteredProjects = computed(() => { const key = projectKeyword.value.trim().toLowerCase(); return projects.value.filter(p => !key || p.name.toLowerCase().includes(key) || options.value.find(c => c.id === p.conferenceId)?.title.toLowerCase().includes(key)); });
const dirty = computed(() => Boolean(project.value && draft.value && JSON.stringify(project.value.draft) !== JSON.stringify(draft.value)));
const template = computed(() => draft.value?.templates.find(t => t.id === templateId.value) ?? draft.value?.templates[0]);
const field = computed(() => template.value?.fields.find(f => f.id === fieldId.value) ?? template.value?.fields[0]);
const queryOptions = computed(() => [...CERTIFICATE_QUERY_FIELDS, { key: "role", label: "职务" }, ...(draft.value?.customFields.map(f => ({ key: `custom.${f.key}`, label: f.label })) ?? [])]);
const textFieldOptions = computed(() => [...queryOptions.value.filter(f => f.key !== "claimCode"), { key: "issueDate", label: "发证日期" }, { key: "literal", label: "固定文字" }]);
const importColumns = computed(() => [...CERTIFICATE_COLUMNS, ...(draft.value?.customFields.map(f => ({ key: `custom.${f.key}`, label: f.label, aliases: [f.label] })) ?? [])]);
const date = (s: string) => new Date(s).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai" });
async function run(task: () => Promise<void>) { if (busy.value) return; busy.value = true; error.value = ""; try { await task(); } catch (e) { error.value = e instanceof Error ? e.message : "操作失败，请重试"; ElMessage.error(error.value); } finally { busy.value = false; } }
function apply(p: CertificateDetail) { project.value = p; draft.value = clone(p.draft); if (!p.draft.templates.some(t => t.id === templateId.value)) templateId.value = p.draft.templates[0].id; }
async function loadLists() { const [list, opts] = await Promise.all([api.list(), api.options()]); projects.value = list.items; options.value = opts.conferences; }
async function confirmDiscard() { if (!dirty.value) return true; try { await ElMessageBox.confirm("当前配置尚未保存，离开后将放弃这些更改。", "未保存的草稿", { type: "warning", confirmButtonText: "放弃并继续", cancelButtonText: "继续编辑" }); return true; } catch { return false; } }
async function open(id: string) { if (!await confirmDiscard()) return; await run(async () => { const sequence = ++loadSequence; ++previewSequence; previewVisible.value = false; previewBusy.value = false; const p = await api.detail(id); if (sequence !== loadSequence) return; apply(p); people.value = []; assets.value = (await api.assets(id)).items; await loadRoster(1); await loadIssues(); navigateTo("/certificates", { projectId: id }); }); }
async function leave() { if (!await confirmDiscard()) return; project.value = null; draft.value = null; navigateTo("/certificates"); await run(loadLists); }
async function refresh() { if (!await confirmDiscard()) return; await run(async () => { await loadLists(); if (project.value) { apply(await api.detail(project.value.id)); assets.value = (await api.assets(project.value.id)).items; await loadRoster(page.value); await loadIssues(); } }); }
async function save() { if (!project.value || !draft.value) return; await run(async () => { const valid = validateCertificateConfig(draft.value); apply(await api.save(project.value!.id, valid, project.value!.draftRevision)); await loadLists(); ElMessage.success("草稿已保存，嘉宾页面仍使用已发布版本。"); }); }
async function create() { await run(async () => { const p = await api.create(createForm); apply(p); createVisible.value = false; assets.value = (await api.assets(p.id)).items; people.value = []; issues.value = []; total.value = 0; tab.value = "basic"; await loadLists(); navigateTo("/certificates", { projectId: p.id }); }); }
async function loadRoster(next = page.value) { if (!project.value) return; page.value = next; try { const response = await api.recipients(project.value.id, next, keyword.value); people.value = response.items; total.value = response.total; } catch (e) { error.value = e instanceof Error ? e.message : '名单加载失败'; } }
async function loadIssues() { if (project.value) { try { issues.value = (await api.issues(project.value.id)).items; } catch (e) { error.value = e instanceof Error ? e.message : '发证记录加载失败'; } } }
async function preview(recipientId?: string, selectedTemplate?: string, version?: number) { if (!project.value || !draft.value) return; previewBusy.value = true; const targetId = project.value.id, requestSequence = ++previewSequence; try { const bytes = await api.preview(targetId, { ...(version ? { version } : { config: validateCertificateConfig(draft.value) }), templateId: selectedTemplate || template.value?.id, recipientId }); if (requestSequence !== previewSequence || project.value?.id !== targetId) return; if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); previewUrl.value = URL.createObjectURL(bytes); previewVisible.value = true; } catch (e) { ElMessage.error(e instanceof Error ? e.message : "预览失败"); } finally { if (requestSequence === previewSequence) previewBusy.value = false; } }
async function upload(event: Event, target: string) { const input = event.target as HTMLInputElement, file = input.files?.[0]; if (!file || !project.value || !draft.value) return; await run(async () => { const a = await api.upload(project.value!.id, file); assets.value.unshift(a); if (target === "background") draft.value!.backgroundAssetId = a.id; else if (target === "font" && template.value) template.value.fontAssetId = a.id; else if (template.value) { template.value.assetId = a.id; if (a.width && a.height) { const ratio = Math.min(1, 4000 / a.width, 4000 / a.height); template.value.width = Math.max(400, Math.round(a.width * ratio)); template.value.height = Math.max(300, Math.round(a.height * ratio)); } } ElMessage.success("素材已上传，请保存配置草稿。"); }); input.value = ""; }
async function loadBackground() { const sequence = ++imageSequence, id = template.value?.assetId; if (backgroundUrl.value) URL.revokeObjectURL(backgroundUrl.value); backgroundUrl.value = ""; if (!id || !project.value) return; try { const blob = await api.asset(project.value.id, id); if (sequence === imageSequence) backgroundUrl.value = URL.createObjectURL(blob); } catch { ElMessage.error("底图加载失败，请重新选择素材。"); } }
function addTemplate() { if (!draft.value || draft.value.templates.length >= 10) return; const t = clone(defaultCertificateConfig().templates[0]); t.id = `type_${crypto.randomUUID().slice(0, 8)}`; t.name = "新证书类型"; draft.value.templates.push(t); templateId.value = t.id; }
async function removeTemplate() { if (!draft.value || !template.value) return; try { await ElMessageBox.confirm("移除后请处理引用此类型的草稿名单。已发布版本不受影响。", "移除证书类型"); draft.value.templates = draft.value.templates.filter(t => t.id !== template.value?.id); templateId.value = draft.value.templates[0].id; } catch { /* cancelled */ } }
function addTextField() { if (!template.value || template.value.fields.length >= 40) return; const f = clone(defaultCertificateConfig().templates[0].fields[0]); f.id = `text_${crypto.randomUUID().slice(0, 8)}`; f.label = "新文字"; f.text = "请输入文字"; template.value.fields.push(f); fieldId.value = f.id; }
function removeTextField() { if (template.value && template.value.fields.length > 1) { template.value.fields = template.value.fields.filter(f => f.id !== field.value?.id); fieldId.value = template.value.fields[0].id; } }
function fieldText(f: CertificateTextField) { if (f.key === "literal") return f.text || "固定文字"; const value = f.key === "issueDate" ? draft.value?.issueDate || "发证日期" : ({ name: "预览姓名", organization: "预览单位", role: "职务", certificateNo: "PREVIEW-001" } as Record<string, string>)[f.key] || draft.value?.customFields.find(x => `custom.${x.key}` === f.key)?.label || f.label; return f.text + value; }
function fieldStyle(f: CertificateTextField) { return { left: `${f.x}%`, top: `${f.y}%`, fontSize: `${f.size / (template.value?.width || 1600) * 100}cqw`, color: f.color, fontWeight: f.weight, lineHeight: f.lineHeight, fontFamily: template.value?.fontFamily, maxWidth: `${f.maxWidth}%`, textAlign: f.align === "start" ? "left" as const : f.align === "end" ? "right" as const : "center" as const, transform: `translate(${f.align === "start" ? "0" : f.align === "end" ? "-100%" : "-50%"}, -50%)` }; }
function startField(e: PointerEvent, f: CertificateTextField) { fieldId.value = f.id; if (!can("write") || busy.value) return; dragging.value = true; (e.target as HTMLElement).setPointerCapture(e.pointerId); }
function moveField(e: PointerEvent) { if (!dragging.value || !field.value) return; const rect = (e.currentTarget as HTMLElement).getBoundingClientRect(); field.value.x = Math.round(Math.min(100, Math.max(0, (e.clientX - rect.left) / rect.width * 100)) * 10) / 10; field.value.y = Math.round(Math.min(100, Math.max(0, (e.clientY - rect.top) / rect.height * 100)) * 10) / 10; }
const queryField = (key: string) => draft.value?.queryFields.find(f => f.key === key);
function toggleQuery(option: { key: string; label: string }) { if (!draft.value) return; const index = draft.value.queryFields.findIndex(f => f.key === option.key); if (index < 0) draft.value.queryFields.push({ ...option, required: true }); else draft.value.queryFields.splice(index, 1); }
function editPerson(row?: CertificateRecipient) { Object.assign(person, row ? { ...clone(row), claimCode: "" } : { id: "", templateId: draft.value?.templates[0].id || "default", name: "", organization: "", role: "", certificateNo: "", claimCode: "", eligible: false, custom: {} }); personVisible.value = true; }
async function savePerson() { if (!project.value) return; await run(async () => { const p = person.id ? await api.update(project.value!.id, person.id, clone(person), project.value!.draftRevision) : await api.add(project.value!.id, clone(person), project.value!.draftRevision); apply(p); personVisible.value = false; person.claimCode = ""; await loadRoster(); await loadLists(); }); }
async function removePerson(row: CertificateRecipient) { if (!project.value) return; try { await ElMessageBox.confirm(`移除 ${row.name} 的草稿记录？已发布名单与已发证书保留。`, "移除草稿名单", { type: "warning" }); } catch { return; } await run(async () => { apply(await api.remove(project.value!.id, row.id, project.value!.draftRevision)); await loadRoster(); await loadLists(); }); }
function showImport() { importVisible.value = true; importError.value = ""; plan.value = null; sheet.value = []; paste.value = ""; importTemplate.value = draft.value?.templates[0].id || "default"; replaceConfirmation.value = ""; }
function setSheet(rows: string[][]) { sheet.value = rows; mapping.value = defaultCertificateMapping(rows[0], draft.value!); plan.value = null; importError.value = ""; }
async function readFile(e: Event) { const input = e.target as HTMLInputElement, file = input.files?.[0]; if (!file) return; try { if (file.size > 10 * 1024 * 1024) throw new Error("名单文件不能超过 10MB"); setSheet(readCertificateSheet(await file.arrayBuffer())); paste.value = ''; } catch (error) { importError.value = error instanceof Error ? error.message : "读取失败"; } input.value = ""; }
function invalidatePaste() { plan.value = null; sheet.value = []; importRows = []; }
function readPaste() { try { setSheet(readCertificateSheet(paste.value)); } catch (e) { importError.value = e instanceof Error ? e.message : "解析失败"; } }
function downloadSample() { downloadCertificateSheet("证书名单导入模板", [{ 姓名: "示例姓名", 单位: "示例单位", 职务: "", 证书编号: "", 领取码: "请替换领取码", 发证资格: "待确认", 唯一外部标识: "", ...Object.fromEntries(draft.value!.customFields.map(f => [f.label, ""])) }]); }
async function checkImport() { if (!project.value || !draft.value) return; importError.value = ""; await run(async () => { try { importRows = mapCertificateRows(sheet.value, mapping.value, draft.value!, importTemplate.value); plan.value = await api.previewImport(project.value!.id, { rows: importRows, mode: importMode.value, draftRevision: project.value!.draftRevision }); } catch (e) { importError.value = e instanceof Error ? e.message : "预检失败"; plan.value = null; } }); }
async function commitImport() { if (!project.value || !plan.value) return; await run(async () => { apply(await api.import(project.value!.id, { rows: importRows, mode: importMode.value, draftRevision: plan.value!.draftRevision, digest: plan.value!.digest, confirmReplace: replaceConfirmation.value })); importVisible.value = false; importRows = []; sheet.value = []; paste.value = ""; await loadRoster(1); await loadLists(); ElMessage.success("名单已写入草稿，发布后嘉宾可访问。"); }); }
async function exportRoster() { if (!project.value) return; await run(async () => { const data = await api.export(project.value!.id); downloadCertificateSheet(project.value!.draft.name, data.items.map(p => ({ 姓名: p.name, 单位: p.organization, 职务: p.role, 证书编号: p.certificateNo, 证书类型: draft.value!.templates.find(t => t.id === p.templateId)?.name || p.templateId, 发证资格: p.eligible ? "已确认" : "待确认", ...Object.fromEntries(draft.value!.customFields.map(f => [f.label, p.custom[f.key] || ""])) }))); }); }
async function publish() { if (!project.value || dirty.value) return; try { await ElMessageBox.confirm("将当前已保存的模板、规则和名单发布到本会议专属链接？", "发布证书项目", { confirmButtonText: "确认发布", cancelButtonText: "继续检查" }); } catch { return; } await run(async () => { apply(await api.publish(project.value!.id, project.value!.draftRevision)); await loadLists(); ElMessage.success("当前会议已发布。"); }); }
async function togglePause() { if (!project.value) return; await run(async () => { apply(await api.state(project.value!.id, { draftRevision: project.value!.draftRevision, paused: !project.value!.paused })); await loadLists(); }); }
async function toggleArchive() { if (!project.value) return; try { await ElMessageBox.confirm(project.value.archived ? '取消本项目归档？' : '归档保留历史数据和专属链接，不改变当前领取状态。停止领取请另行暂停。', '项目归档'); } catch { return; } await run(async () => { apply(await api.state(project.value!.id, { draftRevision: project.value!.draftRevision, paused: project.value!.paused, archived: !project.value!.archived })); await loadLists(); }); }
async function restore(version: number) { if (!project.value) return; try { await ElMessageBox.confirm(`以 V${version} 的配置和名单替换当前草稿？当前已发布页面保持不变。`, "复制历史版本到草稿", { type: "warning" }); } catch { return; } await run(async () => { apply(await api.restore(project.value!.id, version, project.value!.draftRevision)); await loadRoster(1); await loadLists(); }); }
async function revoke(row: CertificateIssue) { if (!project.value) return; try { await ElMessageBox.confirm(row.revokedAt ? "恢复该人员证书领取？" : "撤销该人员所有已发版本的后续领取？已保存到个人设备的文件无法远程删除。", "调整领取状态", { type: "warning" }); } catch { return; } await run(async () => { issues.value = (await api.revoke(project.value!.id, row.id, !row.revokedAt)).items; }); }
async function copyLink() { try { await navigator.clipboard.writeText(project.value!.publicUrl); ElMessage.success("会议专属链接已复制。"); } catch { ElMessage.info("请选中页面上的专属链接进行复制。"); } }
function visit(url: string) { window.open(url, "_blank", "noopener,noreferrer"); }
watch(() => [template.value?.assetId, project.value?.id], loadBackground);
watch(templateId, () => { fieldId.value = template.value?.fields[0].id || ""; });
watch(tab, value => { if (value === "publish") void loadIssues().catch(e => { error.value = e.message; }); });
async function readRegistration() { if (!project.value || !draft.value) return; await run(async () => { const data = await api.registrationSource(project.value!.id, { page: registrationPage.value, templateId: importTemplate.value }); if (!data.rows.length) { importError.value = '本批次没有已确认的报名人员。'; return; } const headers = [...CERTIFICATE_COLUMNS.map(c => c.label), ...draft.value!.customFields.map(f => f.label)]; const rows = data.rows.map(r => [r.name, r.organization, r.role, r.certificateNo, r.claimCode, '待确认', r.externalId, ...draft.value!.customFields.map(f => r.custom[f.key] || '')]); setSheet([headers, ...rows]); paste.value = ''; importError.value = ''; ElMessage.info(`已读取第 ${data.page} 批 ${data.rows.length} 人（共 ${data.total} 人）。领取码请下载留存，发证资格默认为待确认。`); }); }
function downloadCurrentImport() { if (sheet.value.length > 1) downloadCertificateSheet('证书导入名单', sheet.value.slice(1).map(row => Object.fromEntries(sheet.value[0].map((h, i) => [h || `列${i+1}`, row[i] || ''])))); }
const unload = (e: BeforeUnloadEvent) => { if (dirty.value) { e.preventDefault(); e.returnValue = ""; } };
onMounted(async () => { window.addEventListener("beforeunload", unload); await run(async () => { await loadLists(); if (routeQuery.value.projectId) { const id = routeQuery.value.projectId; apply(await api.detail(id)); assets.value = (await api.assets(id)).items; await loadRoster(1); await loadIssues(); } }); });
onBeforeUnmount(() => { ++loadSequence; ++imageSequence; ++previewSequence; window.removeEventListener("beforeunload", unload); if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); if (backgroundUrl.value) URL.revokeObjectURL(backgroundUrl.value); });
</script>

